#[cfg(test)]mod tests{use super::{capability::{Capability,CapabilityPolicy},compiler::Compiler,diagnostics::{Diagnostic,Severity},lexer::Lexer,linker::link_modules,module::ModuleResolver,optimizer::optimize_program,package::{LockedDependency,PackageLock,PackageManifest},parser::{Expr,Parser},typecheck::{Type,TypeChecker},verifier::{verify,VerificationError},vm::{RuntimeError,VM}};fn parse(s:&str)->Vec<super::parser::Expr>{Parser::new(Lexer::new(s)).parse()}fn run(s:&str)->Result<(),super::vm::RuntimeError>{let a=parse(s);let mut c=Compiler::new();c.compile(a);VM::with_functions(c.get_constants().to_vec(),c.get_code().to_vec(),c.get_functions().clone()).run()}#[test]fn arithmetic(){run("print 2 + 3 * 4").unwrap()}#[test]fn float_math(){run("print 2.5 * 4.0").unwrap()}#[test]fn functions(){run("fn add(a,b){ return a+b } print add(7,5)").unwrap()}#[test]fn recursive_functions(){run("fn count(n){ if n > 0 { print n return count(n-1) } return 0 } count(3)").unwrap()}#[test]fn division_by_zero(){assert!(matches!(run("print 10 / 0"),Err(super::vm::RuntimeError::DivisionByZero)))}#[test]fn type_checker_accepts_numeric_program(){let a=parse("secure let x = 10 print x + 2");let mut c=TypeChecker::new();c.check(&a).unwrap();assert_eq!(c.variables().get("x"),Some(&Type::Int));}#[test]fn type_checker_rejects_bad_repeat(){let a=parse("repeat \"nope\" { print 1 }");let mut c=TypeChecker::new();assert!(c.check(&a).is_err())}#[test]fn type_checker_rejects_unknown_function(){let a=parse("print missing(1)");let mut c=TypeChecker::new();assert!(c.check(&a).is_err())}#[test]fn diagnostics_render_with_code_and_help(){let d=Diagnostic::error("E1001","undefined variable: x").at(3,7).with_help("declare x before using it");assert_eq!(d.severity,Severity::Error);assert!(d.to_string().contains("E1001"));assert!(d.to_string().contains("3:7"));assert!(d.to_string().contains("help"))}#[test]fn module_syntax_parses(){let a=parse("import \"lib/math\" as math export secure const answer = 42");assert!(matches!(&a[0],super::parser::Expr::Import{path,..}if path=="lib/math"));assert!(matches!(&a[1],super::parser::Expr::Export{..}))}#[test]fn symbol_analysis_tracks_exports(){let a=parse("export secure const answer = 42");let m=super::symbols::analyze_module("math",&a).unwrap();assert!(m.symbols["answer"].exported)}#[test]fn capabilities_are_deny_by_default(){let p=CapabilityPolicy::deny_all();let mut vm=VM::with_capabilities(vec![],vec![super::compiler::Opcode::NetworkScan,super::compiler::Opcode::Halt],std::collections::HashMap::new(),p);assert!(matches!(vm.run(),Err(RuntimeError::CapabilityDenied(Capability::NetworkScan))))}#[test]fn optimizer_folds_constants(){let a=optimize_program(vec![Expr::Binary{left:Box::new(Expr::Number(2)),op:super::lexer::TokenType::Plus,right:Box::new(Expr::Number(3))}]);assert_eq!(a,vec![Expr::Number(5)]);}#[test]fn linked_modules_are_exposed_through_namespace(){let root=std::env::temp_dir().join(format!("falconcore-lib-{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();let main=root.join("main.falcon");let math=root.join("math.falcon");std::fs::write(&main,"import \"math.falcon\" as math print math::add(2,3)").unwrap();std::fs::write(&math,"export fn add(a,b){ return a+b }").unwrap();let mut r=ModuleResolver::new();let ms=r.resolve(&main).unwrap();let linked=link_modules(&ms,&main).unwrap();assert!(linked.iter().any(|e|matches!(e,Expr::Call{name,..}if name=="math::add"))||linked.iter().any(|e|matches!(e,Expr::Print{..})));let _=std::fs::remove_dir_all(root);}#[test]fn package_lock_matches_manifest(){let mut m=PackageManifest::new("demo","1","main.falcon");m.add_dependency("core","1.0.0");let mut l=PackageLock::default();l.add(LockedDependency{name:"core".into(),version:"1.0.0".into(),source:"registry".into(),checksum:Some("sha256:abc".into())});assert!(l.verify_against(&m).is_ok());}#[test]fn verifier_rejects_bad_constant(){assert!(matches!(verify(&[],&[super::compiler::Opcode::LoadConst(1),super::compiler::Opcode::Halt],&std::collections::HashMap::new()),Err(VerificationError::InvalidConstant{index:1})));}}
